const cds = require('@sap/cds')
const AbstractContainerManagerClient = require('./ctnr-mgr-base')
const { token, fetchResiliently } = require('../../../lib/utils')
const { uuid } = cds.utils
const LOG = cds.log('mtx'), DEBUG = cds.debug('mtx|serverless')

const API = '/serverless/v1/containers'

class ServerlessClient extends AbstractContainerManagerClient {
  constructor(credentials) {
    super({ clientid: credentials.identity?.clientid, url: credentials.identity?.url })
    this.gateway = credentials.url
    this.identity = credentials.identity
    this.certificate = this.identity?.certificate
    this.key = this.identity?.key
    this.certurl = this.identity?.certurl
    this.url = this.identity?.url
    this.clientid = this.identity?.clientid
    this.credentialCache = {}
    this.tokenCache = new Map()
    this.delete = this.remove
  }

  static defaultInstance() {
    ServerlessClient._defaultInstance ??= ServerlessClient.newInstance(ServerlessClient._resolveCredentials())
    return ServerlessClient._defaultInstance
  }

  static _resolveCredentials() {
    const credentials = { ...cds.env.requires.db.credentials }
    let vcap
    const _vcap = () => (vcap ??= (() => { try { return JSON.parse(process.env.VCAP_SERVICES || '{}') } catch { return {} } })())
    if (!credentials.url) {
      const serverless = (_vcap()['hana-cloud'] || []).find(s => s.plan === 'serverless') || (_vcap()['hana-cloud'] || [])[0]
      const gw = credentials.credentials?.url || serverless?.credentials?.url || serverless?.credentials?.credentials?.url
      if (gw) credentials.url = gw
    }
    const iasBinding = (_vcap().identity || [])[0]?.credentials
    if (iasBinding) credentials.identity = iasBinding
    else if (!credentials.identity) credentials.identity = credentials.credentials?.identity
    if (!credentials.identity?.certificate) {
      const identityBinding = ServerlessClient._resolveIdentityBinding()
      if (identityBinding?.certificate) credentials.identity = identityBinding
    }
    return credentials
  }

  static _resolveIdentityBinding() {
    const isIdentity = conf => conf?.kind === 'ias' || conf?.vcap?.label === 'identity'
    for (const conf of Object.values(cds.env.requires || {})) {
      if (isIdentity(conf) && conf.credentials?.certificate) return conf.credentials
    }
    return undefined
  }

  static newInstance(credentials) {
    if (!credentials?.url) cds.error('Serverless gateway URL is not configured in credentials')
    if (!credentials.identity?.certificate) cds.error('No identity (IAS) credentials found for the serverless Tenant API')
    return new ServerlessClient(credentials)
  }

  _tokenFor = async () => {
    const cached = this.tokenCache.get('provider')
    if (cached && cached.expiry >= Date.now() + 30_000) return `Bearer ${cached.access_token}`
    const raw = await token(this.identity, { form: { grant_type: 'client_credentials' }, path: '/oauth2/token' })
    const { access_token, expires_in } = JSON.parse(raw)
    this.tokenCache.set('provider', { access_token, expiry: Date.now() + expires_in * 1000 })
    return `Bearer ${access_token}`
  }

  _api = async (tenant, path, conf = {}) => {
    conf.headers ??= {}
    conf.headers.Authorization ??= await this._tokenFor(tenant)
    conf.headers['Accept'] ??= 'application/json'
    conf.headers['Content-Type'] ??= 'application/json'
    conf.headers['X-CorrelationID'] ??= cds.context?.id
    const { retries, maxRetryAfter } = cds.requires?.multitenancy?.serviceManager ?? cds.requires?.multitenancy?.containerManager ?? {}
    return fetchResiliently(this.gateway + path, conf, { retriesLeft: retries ?? 10, maxRetryAfter: maxRetryAfter ?? 5000 })
  }

  _pollLocation = async (tenant, location, extract) => {
    let attempts = 0
    const maxAttempts = 60, interval = 3000
    for (;;) {
      const { data } = await this._api(tenant, location.startsWith('http') ? location.slice(this.gateway.length) : location, { method: 'GET' })
      const state = extract(data)
      if (state === true) return data
      if (state === 'FAILED') cds.error(`Serverless operation failed for ${location}: ${JSON.stringify(data)}`)
      if (++attempts > maxAttempts) cds.error(`Polling ${location} timed out after ${(interval * maxAttempts) / 1000} seconds`)
      await new Promise(r => setTimeout(r, interval))
    }
  }

  _matchingContainers = (list, tenant) => {
    const base = this._baseName(tenant)
    return (list || []).filter(c => (c.labels || []).includes(`tenant_id=${tenant}`) || c.name === base || (c.name || '').startsWith(`${base}_`))
  }

  _findContainer = async (tenant) => {
    const { data } = await this._api(tenant, API, { method: 'GET' })
    const usable = c => !/(FAILED|DELETED|NOT_EXIST)$/.test(c.status?.state || '')
    return this._matchingContainers(data.data, tenant).find(usable)
  }

  _removeStaleContainers = async (tenant) => {
    const { data } = await this._api(tenant, API, { method: 'GET' })
    const stale = this._matchingContainers(data.data, tenant).filter(c => /FAILED$/.test(c.status?.state || ''))
    for (const c of stale) {
      LOG.info('removing stale serverless container for', { tenant }, 'container', c.name, 'in state', c.status?.state)
      const del = await this._api(tenant, `${API}/${c.id}`, { method: 'DELETE' }).catch(() => ({}))
      const location = del.headers?.['location']
      if (location) await this._pollLocation(tenant, location, d => /(SUCCEEDED|DELETED|NOT_EXIST)$/.test(d.status?.state || '') ? true : false).catch(() => {})
    }
  }

  _findCredentials = async (tenant, containerId) => {
    const { data } = await this._api(tenant, `${API}/${containerId}/credentials`, { method: 'GET' })
    const list = data.data || []
    return list.find(x => (x.state || '').endsWith('SUCCEEDED')) || list[0]
  }

  _credentialsDetail = async (tenant, containerId, credentialId) => {
    const { data } = await this._api(tenant, `${API}/${containerId}/credentials/${credentialId}`, { method: 'GET' })
    return this._toHdiCredentials(data)
  }

  _toHdiCredentials = (c) => ({
    host: c.host,
    port: String(c.port),
    driver: c.driver || 'com.sap.db.jdbc.Driver',
    schema: c.schema,
    hdi_user: c.hdiUser,
    hdi_password: c.hdiPassword,
    user: c.user,
    password: c.password,
    certificate: c.certificate,
    encrypt: true,
    sslTrustAll: false,
    validate_certificate: true,
  })

  get = async (tenant, options = {}) => {
    const { disableCache } = options
    if (!tenant) throw new Error('Tenant name is required')
    if (!disableCache && this.credentialCache[tenant]) return this.credentialCache[tenant]
    const container = await this._findContainer(tenant)
    if (!container) cds.error(`Tenant '${tenant}' does not exist`, { status: 404 })
    const credential = await this._findCredentials(tenant, container.id)
    if (!credential) cds.error(`Tenant '${tenant}' has no usable credentials`, { status: 404 })
    const credentials = await this._credentialsDetail(tenant, container.id, credential.id)
    LOG.info('resolved serverless container for', { tenant }, 'container', container.name, 'schema', credentials.schema)
    return this.credentialCache[tenant] = { name: container.name, tenant_id: tenant, credentials, container, tags: ['hana'] }
  }

  _waitContainerReady = async (tenant, containerId) => {
    await this._pollLocation(tenant, `${API}/${containerId}`, d =>
      d.status?.ready === true || d.status?.state?.endsWith('SUCCEEDED') ? true : (d.status?.state?.endsWith('FAILED') ? 'FAILED' : false)
    )
  }

  _awaitBrokerContainer = async (tenant, attempts = 20, interval = 3000) => {
    for (let i = 0; i < attempts; i++) {
      const container = await this._findContainer(tenant)
      if (container) return container
      await new Promise(r => setTimeout(r, interval))
    }
    return undefined
  }

  create = async (tenant, parameters) => {
    LOG.info('creating serverless HDI container for', { tenant })
    let container = await this._findContainer(tenant)
    const t0 = cds.env.requires.multitenancy?.t0 ?? 't0'
    if (!container && tenant !== t0 && cds.env.requires.multitenancy?.serverless?.autoSubscription) {
      LOG.info('awaiting broker-provisioned serverless container for', { tenant })
      container = await this._awaitBrokerContainer(tenant)
    }
    if (!container) {
      await this._removeStaleContainers(tenant)
      const create = await this._api(tenant, API, {
        method: 'POST',
        data: { name: this._newContainerName(tenant), type: 'hdi', labels: [`tenant_id=${tenant}`, ...(parameters?.customLabels ?? [])] },
      })
      const location = create.headers['location']
      await this._pollLocation(tenant, location, d => d.status?.state?.endsWith('SUCCEEDED') ? true : (d.status?.state?.endsWith('FAILED') ? 'FAILED' : false))
      container = await this._findContainer(tenant)
      if (!container) cds.error(`Serverless container for tenant '${tenant}' not found after creation`)
    }
    await this._waitContainerReady(tenant, container.id)
    let credential = await this._findCredentials(tenant, container.id)
    if (!credential) {
      const create = await this._api(tenant, `${API}/${container.id}/credentials`, { method: 'POST', data: {} })
      const location = create.headers['location']
      await this._pollLocation(tenant, location, d => d.state?.endsWith('SUCCEEDED') ? true : (d.state?.endsWith('FAILED') ? 'FAILED' : false))
      credential = await this._findCredentials(tenant, container.id)
    }
    const credentials = await this._credentialsDetail(tenant, container.id, credential.id)
    LOG.info('created serverless container for', { tenant }, 'container', container.name, 'schema', credentials.schema)
    return this.credentialCache[tenant] = { name: container.name, tenant_id: tenant, credentials, container, tags: ['hana'] }
  }

  getAll = async (tenants = '*', options = {}) => {
    const seed = tenants === '*' ? null : tenants
    const listTenant = seed?.[0]
    let containers = []
    if (listTenant) {
      const { data } = await this._api(listTenant, API, { method: 'GET' })
      containers = (data.data || []).filter(c => (c.labels || []).some(l => l.startsWith('tenant_id=')))
    }
    const results = []
    for (const c of containers) {
      const tenant_id = (c.labels.find(l => l.startsWith('tenant_id=')) || '').split('=')[1]
      if (!tenant_id) continue
      const entry = { labels: { tenant_id: [tenant_id] }, container: c }
      if (options.skipCredentials) { results.push(entry); continue }
      try {
        const { credentials } = await this.get(tenant_id, options)
        results.push({ ...entry, credentials })
      } catch (e) {
        if (e.status === 404) DEBUG?.('skipping tenant', tenant_id, 'without usable credentials')
        else throw e
      }
    }
    return results
  }

  remove = async (tenant) => {
    const container = await this._findContainer(tenant)
    if (!container) { delete this.credentialCache[tenant]; return {} }
    const { data } = await this._api(tenant, `${API}/${container.id}/credentials`, { method: 'GET' })
    for (const cred of data.data || []) {
      const del = await this._api(tenant, `${API}/${container.id}/credentials/${cred.id}`, { method: 'DELETE' })
      const location = del.headers['location']
      if (location) await this._pollLocation(tenant, location, d => d.state?.endsWith('SUCCEEDED') || d.state?.endsWith('DELETED') ? true : false).catch(() => {})
    }
    const del = await this._api(tenant, `${API}/${container.id}`, { method: 'DELETE' })
    const location = del.headers['location']
    if (location) await this._pollLocation(tenant, location, d => d.status?.state?.endsWith('SUCCEEDED') || d.status?.state?.endsWith('DELETED') ? true : false).catch(() => {})
    delete this.credentialCache[tenant]
    return { container: container.id }
  }

  _createParams = (tenant, params = {}, metadata) => {
    const hdiParams = this._hdiParams(tenant, params, metadata) ?? {}
    const result = {}
    const { custom_label } = hdiParams?.create ?? {}
    if (custom_label) {
      const [k] = custom_label.split('=')
      if (k === 'tenant_id') cds.error('"tenant_id" is not allowed as a custom label key')
      result.customLabels = [custom_label]
    }
    return Object.keys(result).length > 0 ? result : null
  }

  _encryptionParams = () => {
    return {}
  }

  _baseName = (tenant) => {
    let sanitized = String(tenant).replace(/[^A-Za-z0-9_]/g, '_').toUpperCase()
    if (!/^[A-Za-z0-9]/.test(sanitized)) sanitized = `T${sanitized}`
    return sanitized.slice(0, 24)
  }

  _newContainerName = (tenant) => {
    const suffix = uuid().replace(/-/g, '').toUpperCase()
    return `${this._baseName(tenant)}_${suffix}`.slice(0, 62)
  }
}

module.exports = ServerlessClient
